public_types.declaration:
pub struct Rect {
    pub x: f32,
    pub y: f32,
    pub width: f32,
    pub height: f32,
}

pub enum Command {
    Rect {
        rect: Rect,
        rgba: [u8; 4],
        radius: f32,
    },
    Image {
        rect: Rect,
        source: u32,
    },
    /// Mask source and row-table indices are separate from image source IDs.
    /// Row origins and y are absolute framebuffer coordinates.
    Glyph {
        source: u32,
        rows: u32,
        y: i32,
        rgba: [u8; 4],
    },
    PushClip(Rect),
    PopClip,
    PushFixed,
    PopFixed,
    Unsupported(&'static str),
}

pub struct SourceImage<'a> {
    pub width: u32,
    pub height: u32,
    pub rgba: &'a [u8],
}

pub struct SourceMask<'a> {
    pub width: u32,
    pub height: u32,
    pub coverage: &'a [u8],
}

pub enum DrawKind {
    Rectangle,
    Image,
    Glyph,
}
